    public override object parseWsTrade(object trade, object market = null)
    {
        //
        // regular v2 trade
        //
        //     {
        //         "type": "trade",
        //         "symbol": "BTCUSD",
        //         "event_id": 122258166738,
        //         "timestamp": 1655330221424,
        //         "price": "22269.14",
        //         "quantity": "0.00004473",
        //         "side": "buy"
        //     }
        //
        // multi data trade
        //
        //    {
        //        "type": "trade",
        //        "symbol": "ETHUSD",
        //        "tid": "1683002242170204", // this is not TS, but somewhat ID
        //        "price": "2299.24",
        //        "amount": "0.002662",
        //        "makerSide": "bid"
        //    }
        //
        Int64? timestamp = this.safeInteger(trade, "timestamp");
        string? id = this.safeString2(trade, "event_id", "tid");
        string? priceString = this.safeString(trade, "price");
        string? amountString = this.safeString2(trade, "quantity", "amount");
        string? side = this.safeStringLower(trade, "side");
        if ((side == null))
        {
            string? marketSide = this.safeStringLower(trade, "makerSide");
            if ((marketSide == "bid"))
            {
                side = "sell";
            } else if ((marketSide == "ask"))
            {
                side = "buy";
            }
        }
        string? marketId = this.safeStringLower(trade, "symbol");
        string? symbol = this.safeSymbol(marketId, market);
        return this.safeTrade(new Dictionary<string, object>() {
            { "id", id },
            { "order", null },
            { "info", trade },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "symbol", symbol },
            { "type", null },
            { "side", side },
            { "takerOrMaker", null },
            { "price", priceString },
            { "cost", null },
            { "amount", amountString },
            { "fee", null },
        }, market);
    }

